import json
import re
import time

from .config import SOURCE, index_path
from .embedding import encoder
from .index import vec_connect
from .store import connect, document

# Terms are grounded in SN56.11 and SN22.59, not generated by the translation provider.
GLOSSARY = {
    "ทุกข์": ("dukkha", "suffering", "sn56.11"),
    "อริยสัจ": ("ariyasacca", "noble truth", "sn56.11"),
    "มรรค": ("magga", "path", "sn56.11"),
    "อนัตตา": ("anattā", "not self", "sn22.59"),
    "ไม่ใช่ตัวตน": ("anattā", "not self", "sn22.59"),
}


def result(doc, sids, language, score=0, context=1, offsets=None):
    ids = list(doc["pali"])
    positions = [ids.index(sid) for sid in sids]
    first, last = min(positions), max(positions)
    context_ids = ids[max(0, first-context): min(len(ids), last+context+1)]
    aligned = sum(sid in doc["english"] for sid in sids)
    return {
        "text_id": doc["text_id"], "segment_ids": sids,
        "original_pali": {sid: doc["pali"][sid] for sid in sids},
        "context_pali": {sid: doc["pali"][sid] for sid in context_ids},
        "source_url": f"{SOURCE}/blob/{doc['revision']}/{doc['source_path']}",
        "source_revision": doc["revision"], "retrieval_language": language,
        "edition": doc["edition"],
        "companion_source_url": f"{SOURCE}/blob/{doc['revision']}/{doc['translation_path']}" if doc["translation_path"] else None,
        "translation_coverage": "complete" if aligned == len(sids) else "partial" if aligned else "none",
        "translator": doc["translator"], "score": score, "category": doc["category"],
        "retrieval_offsets": offsets, "quality_status": "experimental",
    }


def search(query, top_k=5, category=None, method="hybrid", path=None):
    start = time.perf_counter()
    query = query.strip()
    if not query or len(query) > 2000 or not 1 <= top_k <= 20:
        raise ValueError("Query must have 1..2000 characters; top_k must be 1..20")
    with connect() as corpus:
        text_id = query.split(":")[0]
        alias = corpus.execute("SELECT text_id FROM aliases WHERE alias=?", (text_id,)).fetchone()
        if alias:
            text_id = alias[0]
        try:
            doc = document(corpus, text_id)
        except KeyError:
            doc = None
        if doc and (not category or doc["category"] == category):
            if ":" in query and query not in doc["pali"]:
                return {"results": [], "method": "exact", "quality_status": "validated_ids"}
            sids = [query] if ":" in query else [sid for sid in doc["pali"] if sid.startswith(query+":")] or list(doc["pali"])
            return {"results": [result(doc, sids, "identifier", context=0)], "method": "exact",
                    "quality_status": "validated_ids", "elapsed_ms": (time.perf_counter()-start)*1000}
        if doc or re.fullmatch(r"(?=.*\d)[a-z][a-z0-9.-]*(?::[0-9.]+)?", query):
            return {"results": [], "method": "exact", "quality_status": "validated_ids"}
        index = path or index_path()
        if not index.exists():
            raise RuntimeError("Search index is not built; run sutta index")
        conn = vec_connect(index)
        try:
            meta = dict(conn.execute("SELECT key,value FROM metadata"))
            revision = corpus.execute("SELECT value FROM metadata WHERE key='revision'").fetchone()[0]
            if meta["source_revision"] != revision:
                raise RuntimeError("Index revision does not match corpus")
            ranked = []
            if method in ("vector", "hybrid"):
                profile = "bge" if json.loads(meta["model"])["model"] == "BAAI/bge-m3" else "e5"
                model = encoder(profile)
                if meta["model"] != model.fingerprint:
                    raise RuntimeError("Index model differs from installed model; rebuild index")
                vector = model.encode([query], query=True)[0]
                # vec0 KNN can filter category through a candidate set; full corpus filter here
                # avoids missing matches because the wrong category occupied all global neighbors.
                sql = "SELECT rowid,distance FROM vectors WHERE embedding MATCH ? AND k=?"
                args = [vector.tobytes(), max(50, top_k*5)]
                if category:
                    sql += " AND rowid IN (SELECT id FROM chunks WHERE category=?)"
                    args.append(category)
                ranked.append([r[0] for r in conn.execute(sql, args)])
            if method in ("lexical", "hybrid"):
                terms = re.findall(r"[\w]+", query)
                for thai, (pali, english, _) in GLOSSARY.items():
                    if thai in query:
                        terms.extend([pali, english])
                expression = " OR ".join('"' + term.replace('"', '""') + '"' for term in terms)
                if expression:
                    sql = "SELECT lexical.rowid FROM lexical JOIN chunks c ON c.id=lexical.rowid WHERE lexical MATCH ?"
                    args = [expression]
                    if category:
                        sql += " AND c.category=?"
                        args.append(category)
                    sql += " ORDER BY bm25(lexical) LIMIT 100"
                    ranked.append([r[0] for r in conn.execute(sql, args)])
            scores = {}
            for ranking in ranked:
                for rank, cid in enumerate(ranking, 1):
                    scores[cid] = scores.get(cid, 0) + 1 / (60 + rank)
            outputs = []
            seen = set()
            for cid in sorted(scores, key=scores.get, reverse=True):
                row = conn.execute("SELECT * FROM chunks WHERE id=?", (cid,)).fetchone()
                sids = json.loads(row["segment_ids"])
                if any((row["text_id"], sid) in seen for sid in sids):
                    continue
                seen.update((row["text_id"], sid) for sid in sids)
                doc = document(corpus, row["text_id"])
                outputs.append(result(doc, sids, row["language"], scores[cid],
                                      offsets=json.loads(row["offsets"]) if row["offsets"] else None))
                if len(outputs) == top_k:
                    break
            return {"results": outputs, "method": method, "scope": meta["scope"],
                    "quality_status": "experimental", "elapsed_ms": (time.perf_counter()-start)*1000}
        finally:
            conn.close()
